import com.bridger.momentum.*;
import java.nio.file.*;
import java.util.*;
public final class KeybindProfilesRegression {
 static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{Path file=Files.createTempDirectory("keybind-profiles-").resolve("profiles.properties");KeybindProfiles library=new KeybindProfiles(file);Map<String,Integer> first=new LinkedHashMap<>();first.put("key.forward",17);first.put("key.bridgetap.openSettings",0);first.put("key.attack",-100);KeybindProfiles.Profile a=library.save("","AZERTY",first);first.put("key.forward",44);KeybindProfiles.Profile b=library.save("","QWERTY",first);check(a.keys.get("key.forward")==17,"Saved profile changed with source map");library.select(a.id);library=new KeybindProfiles(file);check(library.active().equals(a.id)&&library.next().id.equals(b.id),"Active profile and cycle order not persisted");check(library.list().get(0).keys.get("key.attack")==-100&&library.list().get(0).keys.get("key.bridgetap.openSettings")==0,"Mouse/unbound keys lost");library.rename(a.id,"Renamed");check(new KeybindProfiles(file).find(a.id).keys.equals(a.keys),"Rename overwrote saved keybindings");check(library.list().size()==2&&library.find(a.id).name.equals("Renamed"),"Update duplicated profile");library.select(b.id);check(library.next().id.equals(a.id),"Cycle does not wrap");library.delete(b.id);library=new KeybindProfiles(file);check(library.list().size()==1&&library.active().isEmpty(),"Delete persistence or stale active profile");try{library.save("","",first);throw new AssertionError("Empty name accepted");}catch(IllegalArgumentException good){}System.out.println("PASS: independent named keybind snapshots, mouse/unbound keys, rename, cycle, deletion and restart persistence");}
}
